      <div style="font-family: Arial, sans-serif; font-size: 11px; color: #000; padding: 30px; box-sizing: border-box; width: 750px; background-color: #fff; line-height: 1.35;">
        <!-- Header -->
        <table style="width: 100%; border-collapse: collapse; margin-bottom: 20px; border-bottom: 3px solid #1a365d; padding-bottom: 10px;">
          <tr>
            <td style="padding: 5px 0;">
              <div style="font-size: 24px; color: #1a365d; font-weight: bold;">SISVEN</div>
              <div style="font-size: 10px; color: #718096; text-transform: uppercase; font-weight: bold; margin-top: 3px;">Reporte de Historial de Abonos</div>
            </td>
            <td style="text-align: right; vertical-align: bottom; font-size: 10px; color: #718096; padding: 5px 0;">
              <strong>Fecha Impresión:</strong> ${new Date().toLocaleString()}
            </td>
          </tr>
        </table>

        <!-- Metadatos de la Factura y Resumen Comercial -->
        <table style="width: 100%; border-collapse: separate; border-spacing: 15px 0px; margin-bottom: 25px;">
          <tr>
            <!-- Tarjeta 1 -->
            <td style="background-color: #f7fafc; border: 1px solid #cbd5e0; border-radius: 8px; padding: 15px; vertical-align: top; width: 50%; box-sizing: border-box;">
              <h3 style="margin: 0 0 8px 0; font-size: 11px; color: #2b6cb0; text-transform: uppercase; border-bottom: 1px solid #e2e8f0; padding-bottom: 4px; font-weight: bold;">Detalles de la Cuenta</h3>
              <p style="margin: 6px 0; font-size: 11px;"><strong>Nro Comprobante:</strong> ${we.nro_comprobante}</p>
              <p style="margin: 6px 0; font-size: 11px;"><strong>Proveedor / Acreedor:</strong> ${we.proveedor_nombre}</p>
              <p style="margin: 6px 0; font-size: 11px;"><strong>Fecha Registro:</strong> ${we.fecha_factura||`No especificada`}</p>
            </td>
            <!-- Tarjeta 2 -->
            <td style="background-color: #f7fafc; border: 1px solid #cbd5e0; border-radius: 8px; padding: 15px; vertical-align: top; width: 50%; box-sizing: border-box;">
              <h3 style="margin: 0 0 8px 0; font-size: 11px; color: #2b6cb0; text-transform: uppercase; border-bottom: 1px solid #e2e8f0; padding-bottom: 4px; font-weight: bold;">Resumen Comercial</h3>
              <p style="margin: 6px 0; font-size: 11px;"><strong>Monto Total:</strong> Bs ${e.toFixed(2)}</p>
              <p style="margin: 6px 0; font-size: 11px;"><strong>Abonado hasta hoy:</strong> Bs ${n.toFixed(2)} (${r.toFixed(1)}%)</p>
              <div style="background-color: #edf2f7; height: 6px; border-radius: 3px; margin: 8px 0; overflow: hidden; width: 100%;">
                <div style="background-color: #48bb78; height: 100%; border-radius: 3px; width: ${r}%;"></div>
              </div>
              <p style="margin: 6px 0; font-size: 11px;"><strong>Saldo Restante:</strong> <span style="color: ${t>0?`#e53e3e`:`#38a169`}; font-weight: bold;">Bs ${t.toFixed(2)}</span></p>
            </td>
          </tr>
        </table>

        <!-- Título Sección Tabla -->
        <div style="font-size: 13px; color: #1a365d; font-weight: bold; margin-top: 20px; margin-bottom: 10px; border-left: 4px solid #1a365d; padding-left: 8px;">
          Abonos Realizados
        </div>

        <!-- Tabla de Datos -->
        <table style="width: 100%; border-collapse: collapse; margin-top: 10px;">
          <thead>
            <tr>
              <th style="border: 1px solid #cbd5e0; background-color: #ebf8ff; padding: 8px 10px; font-size: 10px; font-weight: bold; text-transform: uppercase; color: #2b6cb0; text-align: left; width: 20%;">Fecha de Pago</th>
              <th style="border: 1px solid #cbd5e0; background-color: #ebf8ff; padding: 8px 10px; font-size: 10px; font-weight: bold; text-transform: uppercase; color: #2b6cb0; text-align: left; width: 15%;">Método de Pago</th>
              <th style="border: 1px solid #cbd5e0; background-color: #ebf8ff; padding: 8px 10px; font-size: 10px; font-weight: bold; text-transform: uppercase; color: #2b6cb0; text-align: left; width: 25%;">Nota / Observación</th>
              <th style="border: 1px solid #cbd5e0; background-color: #ebf8ff; padding: 8px 10px; font-size: 10px; font-weight: bold; text-transform: uppercase; color: #2b6cb0; text-align: left; width: 25%;">Usuario Registró</th>
              <th style="border: 1px solid #cbd5e0; background-color: #ebf8ff; padding: 8px 10px; font-size: 10px; font-weight: bold; text-transform: uppercase; color: #2b6cb0; text-align: right; width: 15%;">Monto Abono</th>
            </tr>
          </thead>
          <tbody>
            ${je.map((e,t)=>`
              <tr style="${t%2==0?``:`background-color: #f7fafc;`}">
                <td style="border: 1px solid #cbd5e0; padding: 8px 10px; font-size: 11px; font-family: monospace; color: #2d3748;">${e.fecha_pago}</td>
                <td style="border: 1px solid #cbd5e0; padding: 8px 10px; font-size: 11px; color: #2d3748;">
                  <span style="background-color: #e2e8f0; color: #4a5568; padding: 2px 6px; border-radius: 4px; font-size: 9px; font-weight: bold; text-transform: uppercase;">
                    ${e.metodo_pago}
                  </span>
                </td>
                <td style="border: 1px solid #cbd5e0; padding: 8px 10px; font-size: 11px; color: #4a5568;">${e.nota||`-`}</td>
                <td style="border: 1px solid #cbd5e0; padding: 8px 10px; font-size: 11px; color: #2d3748;"><strong>${e.usuario_nombre||`Sistema`}</strong></td>
                <td style="border: 1px solid #cbd5e0; padding: 8px 10px; font-size: 11px; text-align: right; font-family: monospace; font-weight: bold; color: #2f855a;">Bs ${parseFloat(e.monto_pagado).toFixed(2)}</td>
              </tr>
            `).join(``)}
            ${je.length===0?`
              <tr>
                <td colspan="5" style="border: 1px solid #cbd5e0; padding: 20px; text-align: center; color: #a0aec0; font-weight: bold; font-size: 11px;">No se han registrado abonos para esta factura.</td>
              </tr>
            `:``}
          </tbody>
        </table>

        <!-- Footer -->
        <div style="margin-top: 40px; border-top: 1px solid #e2e8f0; padding-top: 10px; text-align: center; font-size: 10px; color: #a0aec0;">
          SISVEN - Systema de Ventas e Inventario © ${new Date().getFullYear()}
        </div>
      </div>
